      <h3 className="text-lg font-bold text-white">{title}</h3>
    </div>
    {children}
  </div>
);

const CopyableItem: React.FC<{ text: string }> = ({ text }) => (
  <div className="group flex items-center justify-between p-3 bg-slate-900/50 rounded-lg border border-slate-700/50 hover:border-primary-500/50 transition-colors">
    <p className="text-slate-200 font-medium text-sm flex-1 mr-4">{text}</p>
    <CopyButton text={text} />
  </div>
);

const CopyButton: React.FC<{ text: string }> = ({ text }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <button
      onClick={handleCopy}
      className="text-slate-500 hover:text-white transition-colors p-1.5 rounded-md hover:bg-slate-700"
      title="Copy to clipboard"
    >
      {copied ? <Check className="w-4 h-4 text-green-400" /> : <Copy className="w-4 h-4" />}
    </button>
  );
};

