  const [seoData, setSeoData] = useState<SeoOutputData | null>(null);
  const [isGeneratingText, setIsGeneratingText] = useState(false);
  const [thumbnailUrl, setThumbnailUrl] = useState<string | null>(null);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [imageError, setImageError] = useState<string | undefined>();

  const handleGenerateContent = async (input: SeoInputData) => {
    setIsGeneratingText(true);
    setSeoData(null);
    setThumbnailUrl(null);
    setImageError(undefined);

    try {
      const data = await generateSeoContent(input);
      setSeoData(data);
    } catch (error) {
      console.error(error);
      alert("Failed to generate content. Please check your API key and try again.");
    } finally {
      setIsGeneratingText(false);
    }
  };

  const handleGenerateThumbnail = async () => {
    if (!seoData?.thumbnailPrompt) return;

    setIsGeneratingImage(true);
    setImageError(undefined);
    try {
      const url = await generateThumbnailImage(seoData.thumbnailPrompt);
      setThumbnailUrl(url);
    } catch (error) {
      console.error(error);
      setImageError("Could not generate image. Please try again later.");
    } finally {
      setIsGeneratingImage(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 pb-20">
      {/* Header */}
      <header className="sticky top-0 z-50 bg-slate-900/80 backdrop-blur-md border-b border-slate-800">
