          <div className="flex items-center gap-3">
            <div className="bg-red-600 p-2 rounded-lg shadow-lg shadow-red-600/20">
              <Youtube className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-white tracking-tight">TubeRank AI</h1>
              <p className="text-xs text-slate-400">Professional SEO Suite</p>
            </div>
          </div>
          <div className="hidden md:block">
            <span className="px-3 py-1 rounded-full bg-emerald-500/10 text-emerald-400 text-xs font-medium border border-emerald-500/20">
              Powered by Gemini 2.0
            </span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-8 space-y-8">
        {/* Intro */}
        <div className="text-center max-w-2xl mx-auto mb-10">
          <h2 className="text-3xl md:text-4xl font-bold text-white mb-4">
            Skyrocket Your <span className="text-transparent bg-clip-text bg-gradient-to-r from-red-500 to-orange-500">YouTube Growth</span>
          </h2>
          <p className="text-slate-400 text-lg">
            Generate viral titles, keyword-rich descriptions, and high-CTR thumbnails in seconds using advanced AI.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Input Sidebar */}
          <div className="lg:col-span-4">
             <div className="lg:sticky lg:top-24">
                <InputSection onGenerate={handleGenerateContent} isGenerating={isGeneratingText} />
             </div>
          </div>

          {/* Results Area */}
          <div className="lg:col-span-8">
            {seoData ? (
              <>
                <OutputSection 
                  data={seoData} 
                  onGenerateImage={handleGenerateThumbnail}
                  isGeneratingImage={isGeneratingImage}
                />
                <ThumbnailDisplay 
                  imageUrl={thumbnailUrl} 
                  loading={isGeneratingImage}
                  error={imageError}
