import { GoogleGenAI, Type } from "@google/genai";
import { SeoInputData, SeoOutputData } from "../types";

// Initialize Gemini Client
// NOTE: In a real production build, ensure process.env.API_KEY is replaced by your build tool (Vite/Webpack)
// or handled via a secure proxy.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateSeoContent = async (input: SeoInputData): Promise<SeoOutputData> => {
  const prompt = `
    You are a world-class YouTube SEO Expert. 
    Generate optimized metadata for a YouTube video based on the following details:

    - Topic: ${input.topic}
    - Main Target Keyword: ${input.mainKeyword}
    - Secondary Keywords: ${input.secondaryKeywords}
    - Language: ${input.language}
    - Tone: ${input.tone}

    Requirements:
    1. Titles: 3 options, under 60 chars, high CTR, natural keyword placement.
    2. Descriptions: 2 options, 300-500 words, keyword rich, include CTA, placeholders for timestamps, and a ranking-friendly summary paragraph.
    3. Tags: 30 comma-separated tags mixing short and long-tail keywords.
    4. Hashtags: 15 relevant hashtags.
    5. Thumbnail Text: Short, big, bold text idea for the thumbnail (max 5 words).
    6. Thumbnail Prompt: A detailed prompt for an AI image generator to create a high-contrast, clickbait-style thumbnail. If the topic allows, lean towards high-emotion or "astrology/mystical" aesthetics if relevant, otherwise keep it bright and bold.
    7. File Name: A hyphen-separated SEO friendly file name for the video file.

    Return the response in strict JSON format.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titles: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "3 SEO optimized titles"
            },
            descriptions: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "2 Long SEO descriptions"
            },
            tags: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "30 SEO tags"
            },
            hashtags: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "15 Hashtags"
            },
            thumbnailText: {
              type: Type.STRING,
              description: "Text to place on the thumbnail"
            },
            thumbnailPrompt: {
              type: Type.STRING,
              description: "Prompt for image generation"
            },
            fileName: {
              type: Type.STRING,
              description: "Suggested video file name"
            }
          },
          required: ["titles", "descriptions", "tags", "hashtags", "thumbnailText", "thumbnailPrompt", "fileName"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned from Gemini");

    return JSON.parse(text) as SeoOutputData;

  } catch (error) {
    console.error("Error generating SEO content:", error);
    throw error;
  }
};

export const generateThumbnailImages = async (prompt: string): Promise<string[]> => {
  const generateOne = async (seedAdjustment: number): Promise<string> => {
    // We add a slight variation to the prompt or use different params to encourage diversity,
    // though the model's inherent randomness usually suffices.
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: {
          parts: [
            { text: `Generate a YouTube thumbnail based on this prompt. Aspect Ratio 16:9. High quality, 2K resolution. Variation ${seedAdjustment}. ` + prompt },
          ],
        },
        config: {
          imageConfig: {
            aspectRatio: "16:9",
            imageSize: "2K"
          },
        },
      });

      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data");
    } catch (e) {
      console.error("Single image generation failed", e);
      throw e;
    }
  };

  // Generate 4 images in parallel
  const promises = [1, 2, 3, 4].map(num => generateOne(num));
  const results = await Promise.allSettled(promises);

  const images = results
    .filter((r): r is PromiseFulfilledResult<string> => r.status === 'fulfilled')
    .map(r => r.value);

  if (images.length === 0) {
    throw new Error("Failed to generate any thumbnails");
  }

  return images;
};

