export const generateSeoContent = async (input: SeoInputData): Promise<SeoOutputData> => {
  // Enhanced prompt for viral analysis and structured output
  const prompt = `
    You are an elite YouTube SEO Strategist and Viral Content Analyst.

    STEP 1: ANALYZE & RESEARCH
    Topic: "${input.topic}"
    User Provided Keywords (if any): "${input.mainKeyword}", "${input.secondaryKeywords}"
    Language: ${input.language}
    Tone: ${input.tone}

    Your goal is to maximize Click-Through Rate (CTR) and Watch Time.
    Ignore the user's keywords if they are weak; instead, identify the current trending, high-volume, low-competition keywords for this specific topic on YouTube and Google Search. Use these "Viral Keywords" to construct the metadata.

    STEP 2: GENERATE CONTENT
    Return a JSON object with the following fields:

    1. titles: Array of 3 strings. Must be under 60 characters. Use the identified viral keywords. High emotional hook.

    2. descriptions: Array of 2 strings. 
       CRITICAL FORMATTING RULE: Do not write a single block of text. 
       Structure the description exactly like this:
       "🔥 [Hook Line]\n\nIn this video, you will learn:\n✨ [Point 1]\n✨ [Point 2]\n✨ [Point 3]\n\n👇 [Strong CTA]\n\n[Timestamps Placeholder]\n\n[SEO Paragraph containing keywords naturally]"

    3. tags: Array of 30 strings. Comma separated list of short-tail and long-tail keywords based on your research.

    4. hashtags: Array of 15 strings.

    5. thumbnailText: Short, punchy text (max 5 words) for the image.

    6. thumbnailPrompt: A highly descriptive prompt for an AI image generator. Style: "YouTube Clickbait", High Contrast, Expressive Faces, 8k resolution.

    7. fileName: SEO optimized hyphenated filename.

    Return ONLY raw JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titles: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "3 SEO optimized titles"
            },
            descriptions: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "2 structured SEO descriptions"
            },
            tags: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "30 SEO tags"
            },
            hashtags: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "15 Hashtags"
            },
            thumbnailText: {
              type: Type.STRING,
              description: "Text overlay for thumbnail"
            },
            thumbnailPrompt: {
              type: Type.STRING,
              description: "Image generation prompt"
            },
            fileName: {
              type: Type.STRING,
              description: "Video file name"
            }
          },
          required: ["titles", "descriptions", "tags", "hashtags", "thumbnailText", "thumbnailPrompt", "fileName"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned from Gemini");

    return JSON.parse(text) as SeoOutputData;

  } catch (error) {
    console.error("Error generating SEO content:", error);
    throw error;
  }
};

export const generateThumbnailImages = async (prompt: string): Promise<string[]> => {
  // Using gemini-2.5-flash-image (Nano Banana) as requested for "YouTube Clickbait" style
  const generateOne = async (index: number): Promise<string> => {
    try {
      // We vary the prompt slightly to ensure different results for each variation
      const variations = [
        "Hyper-realistic, intense expression, bright lighting",
        "Illustrated style, vibrant colors, vector art",
        "Close-up shot, high contrast, dramatic shadows",
        "Wide angle, detailed background, 4k cinematic"
      ];

      const specificStyle = variations[index % variations.length];
      const fullPrompt = `YouTube Thumbnail. ${prompt}. Style: ${specificStyle}. Aspect Ratio 16:9. High Quality.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image', // Nano Banana
        contents: {
          parts: [
            { 
              text: fullPrompt 
            },
          ],
        },
        // Note: Nano banana models do not support responseMimeType or responseSchema
        // Note: aspect ratio is handled via prompt for this model usually, or config if supported.
        // We will strictly check inlineData.
      });

      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data found in response");
    } catch (e) {
      console.error(`Image generation failed for index ${index}`, e);
      // Return a placeholder or re-throw depending on desired behavior. 
      // We re-throw so Promise.allSettled picks it up.
      throw e;
    }
  };

  // Generate 4 images in parallel
  const promises = [0, 1, 2, 3].map(num => generateOne(num));
  const results = await Promise.allSettled(promises);

  const images = results
    .filter((r): r is PromiseFulfilledResult<string> => r.status === 'fulfilled')
    .map(r => r.value);

  if (images.length === 0) {
    throw new Error("Failed to generate any thumbnails. Please try again.");
  }

  return images;
};

