       "🔥 [Hook Line]\n\nIn this video, you will learn:\n✨ [Point 1]\n✨ [Point 2]\n\n👇 [CTA]\n\n[Timestamps]\n\n[SEO Paragraph]\n\n#Hashtag1 #Hashtag2 #Hashtag3"

    3. tags: Array of strings. 
       - Generate a mix of short and long-tail keywords.
       - CRITICAL: The total character count of all tags combined (plus commas) MUST BE UNDER 500 CHARACTERS. This is a hard limit for YouTube.

    4. thumbnailText: Short, punchy text (max 5 words).

    5. thumbnailPrompt: A highly descriptive prompt for an AI image generator. Style: "YouTube Clickbait", High Contrast, Expressive Faces, 4k resolution.

    6. fileName: SEO optimized hyphenated filename.

    Return ONLY raw JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titles: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "3 SEO optimized titles"
            },
            descriptions: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "2 structured SEO descriptions including hashtags"
            },
            tags: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "SEO tags (total length under 500 chars)"
            },
            thumbnailText: {
              type: Type.STRING,
              description: "Text overlay for thumbnail"
            },
            thumbnailPrompt: {
              type: Type.STRING,
              description: "Image generation prompt"
            },
            fileName: {
              type: Type.STRING,
              description: "Video file name"
            }
          },
          required: ["titles", "descriptions", "tags", "thumbnailText", "thumbnailPrompt", "fileName"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned from Gemini");

    return JSON.parse(text) as SeoOutputData;

  } catch (error) {
    console.error("Error generating SEO content:", error);
    throw error;
  }
};

