export const generateThumbnailImages = async (prompt: string): Promise<string[]> => {
  // Using gemini-2.5-flash-image (Nano Banana)
  const generateOne = async (index: number): Promise<string> => {
    try {
      const variations = [
        "Hyper-realistic, intense expression, bright lighting",
        "Illustrated style, vibrant colors, vector art",
        "Close-up shot, high contrast, dramatic shadows",
        "Wide angle, detailed background, 4k cinematic"
      ];

      const specificStyle = variations[index % variations.length];
      const fullPrompt = `Create a YouTube Thumbnail. ${prompt}. Style: ${specificStyle}. Aspect Ratio 16:9. High Quality, 4k resolution.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [{ text: fullPrompt }],
        },
        config: {
          imageConfig: {
            aspectRatio: '16:9'
          }
        }
      });

      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }

      const textPart = response.candidates?.[0]?.content?.parts?.find(p => p.text)?.text;
      if (textPart) {
        console.warn(`Gemini returned text for image request ${index}:`, textPart);
      }

      throw new Error("No image data found in response");
    } catch (e) {
      console.error(`Image generation failed for index ${index}`, e);
      throw e;
    }
  };

  const promises = [0, 1, 2, 3].map(num => generateOne(num));
  const results = await Promise.allSettled(promises);

  const images = results
    .filter((r): r is PromiseFulfilledResult<string> => r.status === 'fulfilled')
    .map(r => r.value);

  if (images.length === 0) {
    const errors = results
      .filter((r): r is PromiseRejectedResult => r.status === 'rejected')
      .map(r => r.reason.message || String(r.reason));

    throw new Error(`Failed to generate thumbnails. Errors: ${errors.join(', ')}`);
  }

  return images;
};

