import React, { useState, useEffect } from 'react';
import { Youtube, Moon, Sun } from 'lucide-react';
import InputSection from './components/InputSection';
import OutputSection from './components/OutputSection';
import ThumbnailDisplay from './components/ThumbnailDisplay';
import { generateSeoContent, generateThumbnailImages, analyzeVideo, auditChannel } from './services/geminiService';
import { SeoInputData, SeoOutputData, AppMode, VideoAnalysisData, ChannelAuditData } from './types';

const App: React.FC = () => {
  // Theme State
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      return 'dark';
    }
    return 'light';
  });

  const [mode, setMode] = useState<AppMode>(AppMode.GENERATOR);

  // Data States
  const [seoData, setSeoData] = useState<SeoOutputData | null>(null);
  const [analysisData, setAnalysisData] = useState<VideoAnalysisData | null>(null);
  const [auditData, setAuditData] = useState<ChannelAuditData | null>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [thumbnailUrls, setThumbnailUrls] = useState<string[]>([]);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [imageError, setImageError] = useState<string | undefined>();

  // Apply Theme
  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  // Handler for Generator Mode
  const handleGenerateContent = async (input: SeoInputData) => {
    setIsProcessing(true);
    setSeoData(null);
    setThumbnailUrls([]);
    setImageError(undefined);

    try {
      const data = await generateSeoContent(input);
      setSeoData(data);
    } catch (error) {
      console.error(error);
      alert("Failed to generate content. Please check your API key and try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  // Handler for Analyzer Mode
  const handleAnalyzeVideo = async (url: string) => {
      setIsProcessing(true);
      setAnalysisData(null);
      setThumbnailUrls([]);

      try {
          const data = await analyzeVideo(url);
          setAnalysisData(data);
      } catch (error) {
          console.error(error);
          alert("Failed to analyze video. Ensure the link is valid.");
      } finally {
          setIsProcessing(false);
      }
  };

  // Handler for Audit Mode
  const handleAuditChannel = async (url: string) => {
      setIsProcessing(true);
      setAuditData(null);

      try {
          const data = await auditChannel(url);
          setAuditData(data);
      } catch (error) {
          console.error(error);
          alert("Failed to audit channel. Ensure the link is valid.");
      } finally {
          setIsProcessing(false);
      }
  };

  const handleGenerateThumbnail = async () => {
    // Determine prompt source based on mode
    let prompt = '';
    if (mode === AppMode.GENERATOR && seoData?.thumbnailPrompt) {
        prompt = seoData.thumbnailPrompt;
    } else if (mode === AppMode.ANALYZER && analysisData?.optimizedData.thumbnailPrompt) {
        prompt = analysisData.optimizedData.thumbnailPrompt;
    }

    if (!prompt) return;

    setIsGeneratingImage(true);
    setImageError(undefined);
    setThumbnailUrls([]);

    try {
      const urls = await generateThumbnailImages(prompt);
      setThumbnailUrls(urls);
    } catch (error) {
      console.error(error);
      setImageError("Could not generate images. Please try again later.");
    } finally {
      setIsGeneratingImage(false);
    }
  };

  // Reset data when switching modes
  useEffect(() => {
      setSeoData(null);
      setAnalysisData(null);
      setAuditData(null);
      setThumbnailUrls([]);
  }, [mode]);

  return (
    <div className="min-h-screen bg-primary-50 dark:bg-slate-950 transition-colors duration-300 pb-20">
      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-primary-100 dark:border-slate-800 transition-colors duration-300">
        <div className="max-w-6xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-red-600 p-2 rounded-lg shadow-lg shadow-red-600/20">
              <Youtube className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-900 dark:text-white tracking-tight">TubeRank AI</h1>
              <p className="text-xs text-slate-500 dark:text-slate-400">Professional SEO Suite</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={toggleTheme}
              className="p-2 rounded-full bg-primary-100 dark:bg-slate-800 text-primary-600 dark:text-slate-400 hover:bg-primary-200 dark:hover:bg-slate-700 transition-all"
              aria-label="Toggle Theme"
            >
              {theme === 'light' ? <Moon className="w-5 h-5" /> : <Sun className="w-5 h-5" />}
            </button>
            <div className="hidden md:block">
              <span className="px-3 py-1 rounded-full bg-primary-100 dark:bg-emerald-500/10 text-primary-700 dark:text-emerald-400 text-xs font-medium border border-primary-200 dark:border-emerald-500/20">
                Powered by Gemini 2.0
              </span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-8 space-y-8">
        {/* Intro */}
        <div className="text-center max-w-2xl mx-auto mb-10">
          <h2 className="text-3xl md:text-4xl font-bold text-slate-900 dark:text-white mb-4">
            Skyrocket Your <span className="text-transparent bg-clip-text bg-gradient-to-r from-red-600 to-orange-500 dark:from-red-500 dark:to-orange-500">YouTube Growth</span>
          </h2>
          <p className="text-slate-600 dark:text-slate-400 text-lg">
            {mode === AppMode.GENERATOR && 'Generate viral titles, keyword-rich descriptions, and high-CTR thumbnails.'}
            {mode === AppMode.ANALYZER && 'Analyze existing videos and get AI-powered optimization suggestions.'}
            {mode === AppMode.AUDIT && 'Deep dive into channel analytics and find opportunities for growth.'}
