            ) : (
              // Empty State
              <div className="h-full min-h-[400px] flex flex-col items-center justify-center text-slate-400 dark:text-slate-600 bg-white/50 dark:bg-slate-900/30 rounded-xl border border-dashed border-primary-200 dark:border-slate-800 transition-all">
                <div className="p-4 bg-primary-50 dark:bg-slate-800/50 rounded-full mb-4">
                  <Youtube className="w-8 h-8 opacity-20 text-slate-900 dark:text-white" />
                </div>
                <p className="text-sm font-medium text-slate-600 dark:text-slate-500">
                    {mode === AppMode.GENERATOR && 'Enter video details to generate magic'}
                    {mode === AppMode.ANALYZER && 'Paste a video URL to start analysis'}
                    {mode === AppMode.AUDIT && 'Paste a channel URL to start audit'}
                </p>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="border-t border-primary-200 dark:border-slate-800 mt-12 py-8 bg-white dark:bg-slate-900 transition-colors duration-300">
