  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { SeoInputData, SeoOutputData, VideoFormat, ChannelAuditData, VideoAnalysisData } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateSeoContent = async (input: SeoInputData): Promise<SeoOutputData> => {
  // Enhanced prompt for viral analysis and structured output
  const isShorts = input.videoFormat === VideoFormat.SHORT;

  const prompt = `
    You are an elite YouTube SEO Strategist and Viral Content Analyst.

    STEP 1: ANALYZE & RESEARCH
    Topic: "${input.topic}"
    Format: ${input.videoFormat} (Important: ${isShorts ? 'Optimize for Shorts Feed, snappy, vertical context' : 'Optimize for Search and Browse features'})
    User Provided Keywords (if any): "${input.mainKeyword}", "${input.secondaryKeywords}"
    Language: ${input.language}
    Tone: ${input.tone}

    Your goal is to maximize Click-Through Rate (CTR) and Watch Time.
    Identify current trending, high-volume, low-competition keywords.

    STEP 2: GENERATE CONTENT
    Return a JSON object with the following fields:

    1. titles: Array of 3 strings. Under 60 chars. High emotional hook. ${isShorts ? 'Include #Shorts if relevant but keep it catchy.' : ''}

    2. descriptions: Array of 2 strings.
       - Include 3-5 viral HASHTAGS at the very end of the description. 
       - CRITICAL FORMATTING:
       "🔥 [Hook Line]\n\nIn this video, you will learn:\n✨ [Point 1]\n✨ [Point 2]\n\n👇 [CTA]\n\n[Timestamps]\n\n[SEO Paragraph]\n\n#Hashtag1 #Hashtag2 #Hashtag3"

    3. tags: Array of strings. 
       - Generate a mix of short and long-tail keywords.
       - CRITICAL: The total character count of all tags combined (plus commas) MUST BE UNDER 500 CHARACTERS. This is a hard limit for YouTube.

    4. thumbnailText: Short, punchy text (max 5 words).

    5. thumbnailPrompt: A highly descriptive prompt for an AI image generator. Style: "YouTube Clickbait", High Contrast, Expressive Faces, 4k resolution.

    6. fileName: SEO optimized hyphenated filename.

    Return ONLY raw JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titles: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "3 SEO optimized titles"
            },
            descriptions: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "2 structured SEO descriptions including hashtags"
            },
            tags: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "SEO tags (total length under 500 chars)"
            },
            thumbnailText: {
              type: Type.STRING,
              description: "Text overlay for thumbnail"
            },
            thumbnailPrompt: {
              type: Type.STRING,
              description: "Image generation prompt"
            },
            fileName: {
              type: Type.STRING,
              description: "Video file name"
            }
          },
          required: ["titles", "descriptions", "tags", "thumbnailText", "thumbnailPrompt", "fileName"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned from Gemini");

    return JSON.parse(text) as SeoOutputData;

  } catch (error) {
    console.error("Error generating SEO content:", error);
    throw error;
  }
};

export const analyzeVideo = async (videoUrl: string): Promise<VideoAnalysisData> => {
    const prompt = `
      I have a YouTube video URL: "${videoUrl}".

      Step 1: Use Google Search to find this video's Title, View Count, and general context/keywords.
      Step 2: Analyze its current SEO (Title, keywords).
      Step 3: Generate OPTIMIZED improvements (Better Title, Better Description, Better Tags, Better Thumbnail idea).

      Return JSON:
      {
         "currentTitle": "The found title of the video",
         "currentViews": "The found view count (e.g. 1.2M views)",
         "seoScore": 75 (0-100 score based on title quality),
         "strengths": ["List 2 things good about it"],
         "weaknesses": ["List 2 things bad about it"],
         "optimizedData": {
            "titles": ["3 better titles..."],
            "descriptions": ["2 better descriptions... formatted with emojis and structure"],
            "tags": ["30 optimized tags (under 500 chars total)"],
            "thumbnailText": "Better text overlay",
            "thumbnailPrompt": "Better thumbnail image prompt",
            "fileName": "optimized-filename"
         }
      }
    `;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", // Supports grounding
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              currentTitle: { type: Type.STRING },
              currentViews: { type: Type.STRING },
              seoScore: { type: Type.NUMBER },
              strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
              weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
              optimizedData: {
                type: Type.OBJECT,
                properties: {
                    titles: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING },
                    description: "3 SEO optimized titles"
                    },
                    descriptions: {
                    type: Type.ARRAY,
