                        <button
                            type="button"
                            onClick={() => handleFormatChange(VideoFormat.SHORT)}
                            className={`flex items-center justify-center gap-2 px-4 py-3 rounded-lg border transition-all ${
                                formData.videoFormat === VideoFormat.SHORT
                                ? 'bg-primary-50 dark:bg-primary-900/30 border-primary-500 text-primary-700 dark:text-primary-300 ring-1 ring-primary-500' 
                                : 'bg-white dark:bg-slate-900 border-primary-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:border-primary-300'
                            }`}
                        >
                            <Smartphone className="w-4 h-4" />
                            <span className="font-medium text-sm">Shorts</span>
                        </button>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <div className="flex justify-between">
                            <label className="text-sm font-medium text-slate-600 dark:text-slate-300">Main Keyword</label>
                            <span className="text-xs text-primary-600 dark:text-primary-400 font-medium">Auto-detected if empty</span>
                        </div>
                        <div className="relative">
                            <Search className="absolute left-3 top-3 w-4 h-4 text-slate-400" />
                            <input
                            type="text"
                            name="mainKeyword"
                            value={formData.mainKeyword}
                            onChange={handleChange}
                            placeholder="AI will find viral keywords..."
                            className="w-full pl-10 bg-primary-50 dark:bg-slate-900 border border-primary-200 dark:border-slate-700 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 focus:ring-2 focus:ring-primary-500 focus:border-transparent outline-none transition-all"
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-600 dark:text-slate-300">Secondary Keywords</label>
                        <input
                        type="text"
                        name="secondaryKeywords"
                        value={formData.secondaryKeywords}
                        onChange={handleChange}
                        placeholder="Optional context..."
                        className="w-full bg-primary-50 dark:bg-slate-900 border border-primary-200 dark:border-slate-700 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 focus:ring-2 focus:ring-primary-500 focus:border-transparent outline-none transition-all"
                        />
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-600 dark:text-slate-300">Language</label>
                        <select
                        name="language"
                        value={formData.language}
                        onChange={handleChange}
                        className="w-full bg-primary-50 dark:bg-slate-900 border border-primary-200 dark:border-slate-700 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                        >
                        {Object.values(Language).map((lang) => (
                            <option key={lang} value={lang}>{lang}</option>
                        ))}
                        </select>
                    </div>

                    <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-600 dark:text-slate-300">Tone</label>
                        <select
                        name="tone"
                        value={formData.tone}
                        onChange={handleChange}
                        className="w-full bg-primary-50 dark:bg-slate-900 border border-primary-200 dark:border-slate-700 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                        >
                        {Object.values(Tone).map((tone) => (
                            <option key={tone} value={tone}>{tone}</option>
                        ))}
                        </select>
                    </div>
                </div>
            </>
        )}

        {(mode === AppMode.ANALYZER || mode === AppMode.AUDIT) && (
             <div className="space-y-2">
                <label className="text-sm font-medium text-slate-700 dark:text-slate-200">
                    {mode === AppMode.ANALYZER ? 'YouTube Video URL' : 'YouTube Channel URL'} <span className="text-red-500">*</span>
                </label>
                <div className="relative">
                    <Youtube className="absolute left-3 top-3 w-5 h-5 text-red-500" />
                    <input
                        type="url"
                        required
                        value={inputUrl}
                        onChange={(e) => setInputUrl(e.target.value)}
                        placeholder={mode === AppMode.ANALYZER ? "https://youtube.com/watch?v=..." : "https://youtube.com/@..."}
                        className="w-full pl-10 bg-primary-50 dark:bg-slate-900 border border-primary-200 dark:border-slate-700 rounded-lg px-4 py-3 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 focus:ring-2 focus:ring-primary-500 focus:border-transparent outline-none transition-all font-medium"
                    />
                </div>
                <p className="text-xs text-slate-500 dark:text-slate-400">
                    Make sure to provide a valid, public URL. AI will browse public data to analyze.
                </p>
            </div>
        )}

        <button
          type="submit"
          disabled={isGenerating}
          className={`w-full mt-6 bg-gradient-to-r text-white font-bold py-3.5 rounded-lg shadow-lg transition-all transform hover:scale-[1.01] active:scale-[0.99] flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed
             ${mode === AppMode.GENERATOR ? 'from-primary-600 to-indigo-600 shadow-primary-500/20' : ''}
             ${mode === AppMode.ANALYZER ? 'from-blue-600 to-cyan-600 shadow-blue-500/20' : ''}
             ${mode === AppMode.AUDIT ? 'from-purple-600 to-pink-600 shadow-purple-500/20' : ''}
          `}
        >
          {isGenerating ? (
            <>
              <Loader2 className="w-5 h-5 animate-spin" />
              Processing...
            </>
          ) : (
            <>
              {mode === AppMode.GENERATOR && <><Sparkles className="w-5 h-5" /> Generate SEO</>}
              {mode === AppMode.ANALYZER && <><Search className="w-5 h-5" /> Analyze Video</>}
              {mode === AppMode.AUDIT && <><BarChart2 className="w-5 h-5" /> Audit Channel</>}
            </>
          )}
        </button>
      </form>
    </div>
  );
};

export default InputSection;

import React from 'react';
