import { GoogleGenAI, Type } from "@google/genai";
import { SeoInputData, SeoOutputData, VideoFormat, ChannelAuditData, VideoAnalysisData } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateSeoContent = async (input: SeoInputData): Promise<SeoOutputData> => {
  const isShorts = input.videoFormat === VideoFormat.SHORT;

  const prompt = `
    You are an elite YouTube SEO Strategist.

    STEP 1: ANALYZE
    Topic: "${input.topic}"
    Format: ${input.videoFormat} (Important: ${isShorts ? 'Optimize for Shorts Feed (Vertical, <60s)' : 'Optimize for Search/Browse (Horizontal)'})
    Keywords: "${input.mainKeyword}", "${input.secondaryKeywords}"
    Language: ${input.language}
    Tone: ${input.tone}

    STEP 2: GENERATE JSON
    Return a JSON object:

    1. titles: Array of 3 strings. Under 60 chars. High CTR.
    2. descriptions: Array of 2 strings.
       - Include 3-5 viral HASHTAGS at the end.
       - Format with line breaks and emojis.
    3. tags: Array of strings. Total length MUST be under 500 chars.
    4. thumbnailText: Short text overlay (max 5 words).
    5. thumbnailPrompt: Highly descriptive image prompt. ${isShorts ? 'Vertical composition (9:16), centered subject, big faces.' : 'Wide cinematic composition (16:9), high contrast.'}
    6. fileName: Hyphenated-seo-filename.

    Return ONLY raw JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titles: { type: Type.ARRAY, items: { type: Type.STRING } },
            descriptions: { type: Type.ARRAY, items: { type: Type.STRING } },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } },
            thumbnailText: { type: Type.STRING },
            thumbnailPrompt: { type: Type.STRING },
            fileName: { type: Type.STRING }
          },
          required: ["titles", "descriptions", "tags", "thumbnailText", "thumbnailPrompt", "fileName"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned from Gemini");

    return JSON.parse(text) as SeoOutputData;

  } catch (error) {
    console.error("Error generating SEO content:", error);
    throw error;
  }
};

export const analyzeVideo = async (videoUrl: string): Promise<VideoAnalysisData> => {
    // Explicit instructions to use the search tool to get real data
    const prompt = `
      Analyze this YouTube video URL: "${videoUrl}".

      STEP 1: REAL DATA EXTRACTION (CRITICAL)
      Use Google Search to find the EXACT and MOST RECENT public metadata for this specific video.
      - Current Title
      - View Count (e.g. "1.2M views")
      - Upload Date (e.g. "2 days ago" or specific date)
      - Like Count
      - Comment Count

      STEP 2: PERFORMANCE ANALYSIS
      Based on the found data:
      - Calculate SEO Score (0-100) based on title keywords and description snippets found.
      - Calculate Viral Score (0-100) based on the views-to-likes ratio and recency.

      STEP 3: VIRAL GROWTH STRATEGY
      Provide 3-5 specific, actionable "Improvement Strategies" to make this video perform better or for the creator's next video.
      Focus on:
      - Improving Click-Through Rate (CTR).
      - Increasing Average View Duration (AVD).
      - Triggering the algorithm via engagement.

      STEP 4: OPTIMIZATION
      Provide optimized Titles, Descriptions, and Tags.

      Return JSON format matching the schema.
    `;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }], // Grounding enabled
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              currentTitle: { type: Type.STRING },
              currentViews: { type: Type.STRING },
              uploadDate: { type: Type.STRING },
              likes: { type: Type.STRING },
              commentCount: { type: Type.STRING },
              seoScore: { type: Type.NUMBER },
              viralScore: { type: Type.NUMBER },
              strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
              weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
              improvementStrategy: { type: Type.ARRAY, items: { type: Type.STRING } },
              optimizedData: {
                type: Type.OBJECT,
                properties: {
                    titles: { type: Type.ARRAY, items: { type: Type.STRING } },
                    descriptions: { type: Type.ARRAY, items: { type: Type.STRING } },
                    tags: { type: Type.ARRAY, items: { type: Type.STRING } },
                    thumbnailText: { type: Type.STRING },
                    thumbnailPrompt: { type: Type.STRING },
