  return (
    <button
      onClick={handleCopy}
      className="text-slate-400 dark:text-slate-500 hover:text-slate-700 dark:hover:text-white transition-colors p-1.5 rounded-md hover:bg-primary-100 dark:hover:bg-slate-700"
