import { GoogleGenAI, Type } from "@google/genai";
import { SeoInputData, SeoOutputData, VideoFormat, SocialInputData, SocialOutputData, SocialPlatform } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateSeoContent = async (input: SeoInputData): Promise<SeoOutputData> => {
  const isShorts = input.videoFormat === VideoFormat.SHORT;

  const prompt = `
    You are an elite YouTube SEO Strategist.

    STEP 1: ANALYZE
    Topic: "${input.topic}"
    Format: ${input.videoFormat} (Important: ${isShorts ? 'Optimize for Shorts Feed (Vertical, <60s)' : 'Optimize for Search/Browse (Horizontal)'})
    Keywords: "${input.mainKeyword}", "${input.secondaryKeywords}"
    Language: ${input.language}
    Tone: ${input.tone}

    STEP 2: GENERATE JSON
    Return a JSON object:

    1. titles: Array of 3 strings. Under 60 chars. High CTR.
    2. descriptions: Array of 2 strings.
       - Include 3-5 viral HASHTAGS at the end.
       - Format with line breaks and emojis.
    3. tags: Array of 20-30 high-traffic keywords and long-tail phrases. The total character count of all tags joined by commas MUST be between 400 and 500 characters. Maximize the usage of the 500 character limit.
    4. thumbnailText: Short text overlay (max 5 words).
    5. thumbnailPrompt: Highly descriptive image prompt. ${isShorts ? 'Vertical composition (9:16), centered subject, big faces.' : 'Wide cinematic composition (16:9), high contrast.'}
    6. fileName: Hyphenated-seo-filename.

    Return ONLY raw JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titles: { type: Type.ARRAY, items: { type: Type.STRING } },
            descriptions: { type: Type.ARRAY, items: { type: Type.STRING } },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } },
            thumbnailText: { type: Type.STRING },
            thumbnailPrompt: { type: Type.STRING },
            fileName: { type: Type.STRING }
          },
          required: ["titles", "descriptions", "tags", "thumbnailText", "thumbnailPrompt", "fileName"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned from Gemini");

    return JSON.parse(text) as SeoOutputData;

  } catch (error) {
    console.error("Error generating SEO content:", error);
    throw error;
  }
};

export const generateSocialContent = async (input: SocialInputData): Promise<SocialOutputData> => {
  const isInstagram = input.platform === SocialPlatform.INSTAGRAM;

  let prompt = '';
  let schema: any = {};

  if (isInstagram) {
    prompt = `
      Act as a Social Media Manager. Create Instagram content for the topic: "${input.topic}".
      Tone: ${input.tone}.
      Keywords/Context: "${input.keywords}".

      Requirements:
      1. Caption: Engaging, uses emojis, line breaks, suitable for a Reel or Post.
      2. Hashtags: 15-20 relevant hashtags.
      3. Story Content: A short, punchy script or text overlay for an Instagram Story promoting this content.
      4. Thumbnail Prompt: A detailed AI image prompt to generate a high-quality cover for an Instagram Reel (9:16 aspect ratio).
    `;
    schema = {
      type: Type.OBJECT,
      properties: {
        platform: { type: Type.STRING, enum: [SocialPlatform.INSTAGRAM] },
        caption: { type: Type.STRING },
        hashtags: { type: Type.ARRAY, items: { type: Type.STRING } },
        storyContent: { type: Type.STRING },
        thumbnailPrompt: { type: Type.STRING },
      },
      required: ["caption", "hashtags", "storyContent", "thumbnailPrompt"]
    };
  } else {
    // Blog
    prompt = `
      Act as an SEO Specialist and Content Writer. Write an SEO-optimized blog post outline and metadata for the topic: "${input.topic}".
      Tone: ${input.tone}.
      Keywords: "${input.keywords}".

      Requirements:
      1. Blog Title: Catchy, includes main keyword (H1).
      2. Meta Description: Under 160 chars, enticing click-through.
      3. Blog Content: A comprehensive structure/mini-article including Introduction, 3-4 Key Headings (H2), bullet points under each, and a Conclusion. Format as a single markdown string.
    `;
    schema = {
      type: Type.OBJECT,
      properties: {
        platform: { type: Type.STRING, enum: [SocialPlatform.BLOG] },
        blogTitle: { type: Type.STRING },
        metaDescription: { type: Type.STRING },
        blogContent: { type: Type.STRING },
      },
      required: ["blogTitle", "metaDescription", "blogContent"]
    };
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned from Gemini");

    const parsed = JSON.parse(text);
    return { ...parsed, platform: input.platform } as SocialOutputData;

  } catch (error) {
    console.error("Error generating Social content:", error);
    throw error;
  }
};

export const generateThumbnailImages = async (prompt: string, aspectRatio: '16:9' | '9:16'): Promise<string[]> => {
  // Using gemini-2.5-flash-image (Nano Banana)
  const generateOne = async (index: number): Promise<string> => {
    try {
      const variations = [
        "Hyper-realistic, intense expression, bright lighting",
        "Illustrated style, vibrant colors, vector art",
        "Close-up shot, high contrast, dramatic shadows",
        "Wide angle, detailed background, 4k cinematic"
      ];

      const specificStyle = variations[index % variations.length];
      const fullPrompt = `Create a YouTube/Social Media Thumbnail. ${prompt}. Style: ${specificStyle}. Aspect Ratio ${aspectRatio}. High Quality, 4k resolution.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [{ text: fullPrompt }],
        },
        config: {
          imageConfig: {
            aspectRatio: aspectRatio
          }
        }
      });

      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }

      throw new Error("No image data found in response");
    } catch (e) {
      console.error(`Image generation failed for index ${index}`, e);
      throw e;
    }
  };

  const promises = [0, 1, 2, 3].map(num => generateOne(num));
  const results = await Promise.allSettled(promises);

  const images = results
    .filter((r): r is PromiseFulfilledResult<string> => r.status === 'fulfilled')
    .map(r => r.value);

  if (images.length === 0) {
    throw new Error(`Failed to generate thumbnails.`);
  }

  return images;
};

